import os # Render reproducible scientific plots without a graphical desktop.
os.environ['MPLBACKEND']='Agg' # Use an offscreen plotting backend for exported report artifacts.
import argparse,json # Read only saved measured evaluation and training records.
import numpy as np # Compute simple summaries from every fixed-denominator case.
import matplotlib.pyplot as plt # Draw standard scientific charts rather than synthesized illustrations.
import complex_operator as base # Reuse canonical experiment path resolution.
COLORS={'initial':'#68758a','active':'#087f8c','random':'#cf7b20'} # Keep strategy colors identical across every panel.
def save(figure,folder,name): # Export a portable vector figure and a directly reviewable raster rendering.
    figure.savefig(folder/f'{name}.svg',bbox_inches='tight');figure.savefig(folder/f'{name}.png',dpi=180,bbox_inches='tight');plt.close(figure) # Preserve actual numeric axes and complete explanatory labels.
def run(family): # Plot the final frozen comparison without fitting models or selecting favorable histories.
    registry=json.loads((base.ROOT/'learning/campaign_learning_index.json').read_text());directory=base.ROOT/registry['families'][family];summary=json.loads((directory/'summary.json').read_text());results={name:json.loads((directory/'final_test'/name/'metrics.json').read_text())['cases'] for name in COLORS};folder=directory/'figures';folder.mkdir(parents=True,exist_ok=True);plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'white'});groups=[row['group'] for row in results['active'][0]['physical_groups']];fig,axes=plt.subplots(1,2,figsize=(15,4.8),layout='constrained') # Derive group labels from the actual masked physical field contract.
    for axis,split in zip(axes,['test','ood']): # Keep ordinary held-out histories and out-of-domain histories separate.
        x=np.arange(len(groups));count=sum(row['split']==split for row in results['active']) # Use the complete fixed history count for each panel.
        for offset,(strategy,color) in enumerate(COLORS.items()): # Display matched initial, active and random predictions on the same histories.
            rows=[row for row in results[strategy] if row['split']==split];values=[np.mean([next(item['relative_L2']/item['threshold'] for item in row['physical_groups'] if item['group']==group) for row in rows]) for group in groups];axis.bar(x+(offset-1)*.25,values,.24,label=strategy,color=color) # Plot physical-group mean error divided by its previously frozen acceptance threshold.
        axis.axhline(1,color='#b52435',linestyle='--',linewidth=1.2,label='registered field threshold');axis.set_xticks(x,[group.replace('_','\n') for group in groups]);axis.set_yscale('log');axis.set_ylabel('Mean relative field error / field threshold');axis.set_title(f'{split.upper()} — all {count} histories');axis.grid(axis='y',alpha=.2);axis.set_axisbelow(True) # A value above one indicates a failed group mean, while case-level gates remain separately reported.
    axes[0].legend(frameon=False,ncols=2,fontsize=9);fig.suptitle(f'{family.capitalize()}: complete free-field cold rollout, frozen models\nErrors are against the selected discrete native FEM reference; no numerical correction',fontsize=12);save(fig,folder,'physical_group_comparison') # Avoid claiming continuum fidelity or nonlinear equilibrium from supervised field errors.
    pairs=summary['paired_error_changes'];fig,axis=plt.subplots(figsize=(12,4.8),layout='constrained');x=np.arange(len(pairs)) # Preserve same-case before/after comparisons including every negative example.
    for strategy,color in COLORS.items(): axis.plot(x,[row[f'{strategy}_error']*100 for row in pairs],marker='o',label=strategy,color=color,linewidth=1.8) # Plot measured physical-group mean relative errors without averaging away difficult cases.
    axis.set_xticks(x,[row['id'].replace('friction_','')+'\n'+row['split'] for row in pairs]);axis.set_ylabel('Mean of physical-group relative L2 errors (%)');axis.set_xlabel('Registered whole loading history');axis.set_title('Same native reference histories before and after feedback');axis.legend(frameon=False);axis.grid(axis='y',alpha=.2);save(fig,folder,'paired_history_errors') # Preserve the exact case denominator and distinguish test from OOD labels.
    fig,axes=plt.subplots(1,2,figsize=(12,4.6),layout='constrained') # Compare actual validation trajectories for both independent seed lineages.
    for axis,seed in zip(axes,[17,41]): # Retain both seeds rather than showing only the selected best predictor.
        initial=json.loads((directory/'initial'/f'seed_{seed}'/'history.json').read_text());initial_epochs=initial['epochs_executed'];axis.plot([row['epoch'] for row in initial['history']],[row['validation_cold_rollout_normalized_RMSE'] for row in initial['history']],color=COLORS['initial'],label='shared initial');offset=initial_epochs # Preserve the original measured initial optimization, including copied-checkpoint provenance.
        for branch in ['active','random']: # Plot each actually executed continuation round, including candidates later rejected by rollback.
            offset=initial_epochs # Both strategies begin from identical initial training checkpoints.
            for number,path in enumerate(sorted((directory/branch).glob('round_*/'+f'seed_{seed}/history.json')),1): # Read recorded optimizer stages in their actual order.
                history=json.loads(path.read_text());axis.plot([offset+row['epoch'] for row in history['history']],[row['validation_cold_rollout_normalized_RMSE'] for row in history['history']],color=COLORS[branch],label=branch if number==1 else None);offset+=history['epochs_executed'] # Do not replace failed or nonmonotone measured curves with smooth invented convergence.
        axis.set_title(f'Seed {seed}');axis.set_xlabel('Cumulative registered epochs');axis.set_ylabel('Validation cold-rollout normalized RMSE');axis.grid(alpha=.2);axis.legend(frameon=False) # Keep validation selection metrics distinct from held-out physical-group relative errors.
    fig.suptitle('Measured training trajectories; continuation candidates may be rolled back',fontsize=12);save(fig,folder,'validation_training_curves');base.write(folder/'manifest.json',{'family':family,'plot_source_sha256':base.digest(__file__),'figures':['physical_group_comparison','paired_history_errors','validation_training_curves'],'sources':['summary.json','final_test/*/metrics.json','initial/seed_*/history.json','active/round_*/seed_*/history.json','random/round_*/seed_*/history.json'],'uses_all_registered_test_and_ood_histories':True,'native_reference_scope':summary['reference_scope']}) # Make the scientific figure provenance explicit and reproducible.
if __name__=='__main__': # Generate report graphics only from a completed canonical frozen evaluation.
    parser=argparse.ArgumentParser();parser.add_argument('--family',choices=['friction','rebar','thermoplastic'],required=True);run(parser.parse_args().family) # Keep family identity explicit in saved artifacts.
